mapper.insert:
insert into sys_user (
    merchant_id, user_name, password, openid,
    phone_country_code, phone_hash, phone_masked, phone_bound_time
) values (
    #{merchantId}, #{userName}, #{password}, #{openid},
    #{phoneCountryCode}, #{phoneHash}, #{phoneMasked}, #{phoneBoundTime}
)

mapper.select:
select u.user_id, u.merchant_id, u.user_name, u.password, u.openid, u.phone_country_code, u.phone_hash, u.phone_masked, u.phone_bound_time, u.create_time, u.update_time from sys_user u join merchant_users mu on mu.user_id = u.user_id and mu.merchant_id = #{merchantId} and mu.status = 'ENABLED' where u.user_name like concat('%', #{keyword}, '%')
and u.user_id not in
#{id}
order by u.user_name asc limit #{limit}
